// FSRS-6 port validated against the py-fsrs v6.3.0 reference fixture
// (values generated by py-fsrs 6.3.0; republished in the fsrs_ex package's
// test/fixtures/py_fsrs_v6_3_0_fixture.json). Fuzzing is disabled in the fixture.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  APP_DEFAULT_CONFIG,
  CardState,
  DEFAULT_PARAMETERS,
  FsrsScheduler,
  PY_FSRS_DEFAULT_CONFIG,
  pyRound,
  seededRandom,
  simulateWorkload,
  type FsrsCardState,
  type Rating,
} from '../../shared/fsrs.ts';

const t = (iso: string) => Date.parse(iso);
const close = (actual: number | null, expected: number, eps = 1e-9) =>
  assert.ok(actual != null && Math.abs(actual - expected) < eps, `expected ${expected}, got ${actual}`);

const newCard = (): FsrsCardState => ({ state: CardState.New, step: null, stability: null, difficulty: null, due: null, lastReview: null });

test('default parameters match py-fsrs 6.3.0', () => {
  assert.deepEqual(
    [...DEFAULT_PARAMETERS],
    [0.212, 1.2931, 2.3065, 8.2956, 6.4133, 0.8334, 3.0194, 0.001, 1.8722, 0.1666, 0.796, 1.4835, 0.0614, 0.2629, 1.6483, 0.6014, 1.8729, 0.5425, 0.0912, 0.0658, 0.1542],
  );
});

test('review trace matches py-fsrs 6.3.0 fixture (default scheduler, no fuzz)', () => {
  const s = new FsrsScheduler({ ...PY_FSRS_DEFAULT_CONFIG, enableFuzzing: false });
  const trace: Array<{ rating: Rating; at: string; state: number; step: number | null; stability: number; difficulty: number; due: string }> = [
    { rating: 3, at: '2024-01-01T08:00:00Z', state: 1, step: 1, stability: 2.3065, difficulty: 2.118103970459016, due: '2024-01-01T08:10:00Z' },
    { rating: 1, at: '2024-01-01T08:02:00Z', state: 1, step: 0, stability: 0.7750839828558984, difficulty: 7.394502741279718, due: '2024-01-01T08:03:00Z' },
    { rating: 3, at: '2024-01-04T08:03:00Z', state: 1, step: 1, stability: 4.308886950836501, difficulty: 7.382336607835277, due: '2024-01-04T08:13:00Z' },
    { rating: 2, at: '2024-01-14T08:00:00Z', state: 1, step: 1, stability: 10.70891165892449, difficulty: 8.24750142646382, due: '2024-01-14T08:10:00Z' },
    { rating: 4, at: '2024-02-20T08:00:00Z', state: 2, step: null, stability: 53.32131679129381, difficulty: 7.647126438918395, due: '2024-04-13T08:00:00Z' },
  ];
  let card = newCard();
  for (const step of trace) {
    const out = s.review(card, step.rating, t(step.at));
    card = out.card;
    assert.equal(card.state, step.state, `state after ${step.at}`);
    assert.equal(card.step, step.step, `step after ${step.at}`);
    close(card.stability, step.stability, 1e-9);
    close(card.difficulty, step.difficulty, 1e-9);
    assert.equal(card.due, t(step.due), `due after ${step.at}`);
    assert.equal(card.lastReview, t(step.at));
  }
});

test('rescheduling from unsorted logs matches py-fsrs 6.3.0 fixture', () => {
  const s = new FsrsScheduler({ ...PY_FSRS_DEFAULT_CONFIG, enableFuzzing: false });
  const { card } = s.replay([
    { rating: 4, reviewedAt: t('2024-03-08T09:00:00Z') },
    { rating: 3, reviewedAt: t('2024-03-01T09:00:00Z') },
    { rating: 1, reviewedAt: t('2024-03-01T09:02:00Z') },
  ]);
  assert.equal(card.state, CardState.Review);
  assert.equal(card.step, null);
  close(card.stability, 9.719632887522758);
  close(card.difficulty, 6.5090953428844935);
  assert.equal(card.due, t('2024-03-18T09:00:00Z'));
  assert.equal(card.lastReview, t('2024-03-08T09:00:00Z'));
});

test('custom scheduler config (retention 0.87, 3 learning steps) behaves per py-fsrs rules', () => {
  const s = new FsrsScheduler({
    parameters: DEFAULT_PARAMETERS,
    desiredRetention: 0.87,
    learningSteps: [60, 95, 300],
    relearningSteps: [90, 900],
    maximumInterval: 4000,
    enableFuzzing: false,
  });
  const now = t('2024-01-01T00:00:00Z');
  const hard = s.review(newCard(), 2, now);
  // Hard on step 0 with >=2 steps -> mean of first two steps, step unchanged.
  assert.equal(hard.card.step, 0);
  assert.equal(hard.card.due, now + ((60 + 95) / 2) * 1000);
  const good = s.review(newCard(), 3, now);
  assert.equal(good.card.step, 1);
  assert.equal(good.card.due, now + 95 * 1000);
});

test('retrievability is exactly the desired retention after one stability interval', () => {
  const s = new FsrsScheduler();
  for (const stability of [1, 5, 30, 365]) {
    close(s.retrievabilityAt(stability, stability), 0.9, 1e-12);
  }
  const card: FsrsCardState = { state: 2, step: null, stability: 10, difficulty: 5, due: 0, lastReview: t('2024-06-01T00:00:00Z') };
  // Whole-day elapsed time like py-fsrs: 23h59m later still counts as 0 days.
  assert.equal(s.retrievability(card, t('2024-06-01T23:59:00Z')), 1);
  assert.ok(s.retrievability(card, t('2024-06-02T00:00:00Z')) < 1);
});

test('app config (no sub-day steps) schedules new cards in whole days', () => {
  const s = new FsrsScheduler({ ...APP_DEFAULT_CONFIG, enableFuzzing: false });
  const now = t('2024-05-01T10:00:00Z');
  const intervals = ([1, 2, 3, 4] as Rating[]).map((r) => s.review(newCard(), r, now).scheduledDays);
  // S0 = w0..w3 = 0.212, 1.2931, 2.3065, 8.2956 -> round, min 1 day
  assert.deepEqual(intervals, [1, 1, 2, 8]);
  for (const r of [1, 2, 3, 4] as Rating[]) assert.equal(s.review(newCard(), r, now).card.state, CardState.Review);
});

test('lapse in Review without relearning steps stays in Review with a short interval', () => {
  const s = new FsrsScheduler({ ...APP_DEFAULT_CONFIG, enableFuzzing: false });
  const now = t('2024-05-01T10:00:00Z');
  let card = s.review(newCard(), 3, now).card;
  card = s.review(card, 3, card.due!).card;
  const before = card.stability!;
  const lapse = s.review(card, 1, card.due!);
  assert.equal(lapse.card.state, CardState.Review);
  assert.ok(lapse.card.stability! < before, 'stability decreases after a lapse');
  assert.ok(lapse.scheduledDays >= 1);
});

test('ratings are monotonic: Again < Hard <= Good < Easy stability on a review card', () => {
  const s = new FsrsScheduler({ ...APP_DEFAULT_CONFIG, enableFuzzing: false });
  const base: FsrsCardState = { state: 2, step: null, stability: 12, difficulty: 5, due: 0, lastReview: t('2024-01-01T00:00:00Z') };
  const at = t('2024-01-13T00:00:00Z');
  const st = ([1, 2, 3, 4] as Rating[]).map((r) => s.review(base, r, at).card.stability!);
  assert.ok(st[0] < st[1] && st[1] <= st[2] && st[2] < st[3], JSON.stringify(st));
});

test('fuzzing is deterministic with a seeded generator and stays within range', () => {
  const s = new FsrsScheduler({ ...APP_DEFAULT_CONFIG, enableFuzzing: true });
  const base: FsrsCardState = { state: 2, step: null, stability: 40, difficulty: 5, due: 0, lastReview: t('2024-01-01T00:00:00Z') };
  const at = t('2024-02-10T00:00:00Z');
  const a = s.review(base, 3, at, seededRandom(7)).scheduledDays;
  const b = s.review(base, 3, at, seededRandom(7)).scheduledDays;
  assert.equal(a, b);
  const unfuzzed = new FsrsScheduler({ ...APP_DEFAULT_CONFIG, enableFuzzing: false }).review(base, 3, at).scheduledDays;
  assert.ok(Math.abs(a - unfuzzed) <= Math.ceil(unfuzzed * 0.1) + 2, `fuzzed ${a} vs ${unfuzzed}`);
});

test('pyRound rounds half to even like Python', () => {
  assert.deepEqual([0.5, 1.5, 2.5, 3.5, 2.4, 2.6].map(pyRound), [0, 2, 2, 4, 2, 3]);
});

test('higher desired retention increases simulated workload', () => {
  const low = simulateWorkload({ desiredRetention: 0.8, cards: 100, days: 180 });
  const high = simulateWorkload({ desiredRetention: 0.95, cards: 100, days: 180 });
  assert.ok(high.reviewsPerDay > low.reviewsPerDay, `${high.reviewsPerDay} > ${low.reviewsPerDay}`);
});

test('invalid inputs are rejected', () => {
  assert.throws(() => new FsrsScheduler({ parameters: [1, 2, 3] }));
  assert.throws(() => new FsrsScheduler({ desiredRetention: 1.2 }));
  assert.throws(() => new FsrsScheduler().review(newCard(), 5 as Rating, Date.now()));
});
